const NL = String.fromCharCode(10);
const i = $input.first().json.body ?? $input.first().json;
const message = String(i.message ?? '').trim();
if (!message) { throw new Error('Thiếu message'); }
const KB = [
  { tags: ['bảo hành', 'hư', 'hỏng', 'lỗi', 'sửa'], text: 'Bảo hành tính từ ngày giao thực tế theo từng sản phẩm. Hàng cồng kềnh được bảo hành tại nhà; hàng nhỏ gửi về trung tâm, CaraVeso chịu phí hai chiều trong phạm vi bảo hành.' },
  { tags: ['đổi', 'trả', 'hoàn', '7'], text: 'Đổi hoặc trả trong 7 ngày kể từ ngày giao thực tế, kèm lý do và ảnh/video. Hàng phải còn phụ kiện, bao bì, tem nhãn. Hàng lỗi do vận chuyển hoặc nhà sản xuất cần video mở hàng.' },
  { tags: ['giao', 'vận chuyển', 'ship', 'phí', 'lắp'], text: 'Giao hàng theo cấp độ cồng kềnh 1-4. Hàng cồng kềnh do đội xe CaraVeso giao và lắp đặt theo lịch khách chọn. Phí vận chuyển hiển thị ở bước thanh toán.' },
  { tags: ['thanh toán', 'cod', 'qr', 'chuyển khoản', 'cọc'], text: 'Thanh toán COD khi nhận hàng hoặc QR ngân hàng. Đơn trên 20.000.000đ cần đặt cọc 30% qua QR trong 15 phút; hết hạn đơn tự hủy.' },
  { tags: ['voucher', 'khuyến mãi', 'giảm'], text: 'Mỗi đơn áp dụng tối đa 1 voucher. Voucher công khai, voucher trong ví và voucher gán riêng có điều kiện khác nhau, hiển thị ở bước thanh toán.' },
  { tags: ['giờ', 'làm việc', 'hotline', 'liên hệ', 'cskh'], text: 'CaraVeso làm việc 8:00-17:30 thứ 2 đến thứ 7. Hotline 1900 080906, email caravesodesign@com.vn. Ngoài giờ, khách để lại tin nhắn và được trả lời vào ngày làm việc kế tiếp.' },
  { tags: ['kích thước', 'phòng', 'diện tích', 'phù hợp'], text: 'CaraVeso tư vấn nội thất theo diện tích phòng và kích thước cửa, thang máy, hành lang. Khách cung cấp chiều dài, rộng, cao để được gợi ý phù hợp.' }
];
const stop = ['và', 'là', 'của', 'cho', 'có', 'không', 'được', 'tôi', 'mình', 'bạn', 'anh', 'chị', 'em', 'cái', 'chiếc', 'với', 'thì', 'một', 'những', 'các', 'ở', 'này', 'đó', 'ạ', 'nhé', 'vậy', 'sao', 'nào', 'bao', 'nhiêu', 'muốn', 'cần'];
const tok = (s) => String(s || '').toLowerCase().split(/[^\p{L}\p{N}]+/u).filter((w) => w.length > 1 && !stop.includes(w));
const q = tok(message);
const ranked = KB.map((k) => { const kt = tok(k.text); let score = 0; for (const t of q) { if (k.tags.includes(t)) score += 2; else if (kt.includes(t)) score += 1; } return { text: k.text, score }; }).sort((a, b) => b.score - a.score);
const hits = ranked.filter((k) => k.score > 0).slice(0, 3);
const policyText = (hits.length ? hits : ranked.slice(0, 2)).map((k) => '- ' + k.text).join(NL);
const products = Array.isArray(i.context?.products) ? i.context.products.slice(0, 8) : [];
const productText = products.length ? products.map((p, n) => `${n + 1}. ${p.name} | Giá: ${p.price ?? 'liên hệ'} | Chất liệu: ${p.material ?? '—'} | Màu: ${p.color ?? '—'} | Kích thước: ${p.dimensions ?? '—'} | Tồn kho: ${p.stockStatus ?? 'còn hàng'}`).join(NL) : '(Không có sản phẩm phù hợp)';
const systemPrompt = 'Bạn là trợ lý tư vấn nội thất của CaraVeso. Trả lời tiếng Việt, xưng em, gọi khách là anh/chị. Chỉ trả lời về sản phẩm nội thất và chính sách của CaraVeso; câu ngoài phạm vi thì từ chối lịch sự. Chỉ dùng thông tin trong NGỮ CẢNH, không bịa tên sản phẩm, giá, tồn kho hay khuyến mãi. Thiếu thông tin thì hỏi lại tối đa 1 câu. Nếu khách muốn gặp nhân viên, phàn nàn hoặc hỏi về đơn hàng cụ thể thì đặt handoff = true. Trả lời tối đa 120 từ, chỉ trả về JSON đúng schema.';
const userText = 'NGỮ CẢNH CHÍNH SÁCH:' + NL + policyText + NL + NL + 'SẢN PHẨM LIÊN QUAN:' + NL + productText + NL + NL + 'CÂU HỎI CỦA KHÁCH:' + NL + message;
const history = Array.isArray(i.history) ? i.history.slice(-8) : [];
const contents = [];
for (const h of history) { const role = h.role === 'assistant' ? 'model' : 'user'; if (!h.content) continue; const last = contents[contents.length - 1]; if (last && last.role === role) last.parts[0].text += NL + h.content; else contents.push({ role, parts: [{ text: h.content }] }); }
const last = contents[contents.length - 1];
if (last && last.role === 'user') last.parts[0].text += NL + NL + userText; else contents.push({ role: 'user', parts: [{ text: userText }] });
return [{ json: { sessionId: String(i.sessionId ?? ''), allowedProducts: products.map((p) => p.name).filter(Boolean), geminiBody: { systemInstruction: { parts: [{ text: systemPrompt }] }, contents, generationConfig: { temperature: 0.4, maxOutputTokens: 1024, responseMimeType: 'application/json', responseSchema: { type: 'OBJECT', properties: { reply: { type: 'STRING' }, handoff: { type: 'BOOLEAN' }, suggestedProducts: { type: 'ARRAY', items: { type: 'STRING' } } }, required: ['reply', 'handoff'] } } } } }];

const res = $input.first().json;
const base = { sessionId: $('Build Prompt').first().json.sessionId, reply: '', handoff: false, suggestedProducts: [], error: null };
if (res && res.error) { base.reply = 'Xin lỗi anh/chị, trợ lý đang bận. Anh/chị để lại tin nhắn để nhân viên hỗ trợ ngay nhé.'; base.handoff = true; base.error = 'AI_UNAVAILABLE'; return [{ json: base }]; }
const raw = ((res.candidates && res.candidates[0] && res.candidates[0].content && res.candidates[0].content.parts) || []).map((p) => p.text || '').join('').trim();
if (!raw) { base.reply = 'Xin lỗi anh/chị, em chưa có câu trả lời phù hợp. Anh/chị để lại tin nhắn để nhân viên hỗ trợ nhé.'; base.handoff = true; base.error = 'AI_EMPTY'; return [{ json: base }]; }
let parsed;
try { parsed = JSON.parse(raw); } catch (e) { parsed = { reply: raw, handoff: false, suggestedProducts: [] }; }
base.reply = String(parsed.reply || raw).trim();
base.handoff = Boolean(parsed.handoff);
const allowed = new Set(($('Build Prompt').first().json.allowedProducts) || []);
base.suggestedProducts = Array.isArray(parsed.suggestedProducts) ? parsed.suggestedProducts.filter((n) => allowed.has(n)).slice(0, 3) : [];
return [{ json: base }];
